class Solution {
public:
    int calculateTime(string keyboard, string word) {
        vector<int> position(26);
        for (int i = 0; i < 26; ++i) {
            position[keyboard[i] - 'a'] = i;
        }
        int cursor = 0;
        int total = 0;
        for (char c : word) {
            int next = position[c - 'a'];
            total += abs(next - cursor);
            cursor = next;
        }
        return total;
    }
};
